MagickBooleanType SetQuantumDepth(const Image *image, QuantumInfo *quantum_info, const size_t depth) {
  assert(image != (Image *) NULL);
  assert(image->signature == MagickSignature);
  assert(quantum_info != (QuantumInfo *) NULL);
  assert(quantum_info->signature == QuantumInfoSignature);

#if defined(MAGICKCORE_DEBUG)
  (void) LogMagickEvent(CoderEvent, GetMagickModule(), "SetQuantumDepth: %s", image->filename);
#endif

  quantum_info->depth = depth;

  if (image->quantum_info != (QuantumInfo *) NULL)
    return(MagickTrue);

  switch (quantum_info->format)
  {
    case CharQuantum:
      if (depth <= 8)
        image->quantum_info = quantum_info;
      break;
    case ShortQuantum:
      if (depth <= 16)
        image->quantum_info = quantum_info;
      break;
    case IntegerQuantum:
    case LongQuantum:
    case SizeQuantum:
      if (depth <= 32)
        image->quantum_info = quantum_info;
      break;
    case FloatQuantum:
      if (depth <= 32)
        image->quantum_info = quantum_info;
      break;
    case DoubleQuantum:
      if (depth <= 64)
        image->quantum_info = quantum_info;
      break;
    case UndefinedQuantum:
    default:
      break;
  }

  if (image->quantum_info != (QuantumInfo *) NULL)
    return(MagickTrue);

  return(MagickFalse);
}

