MagickBooleanType SetQuantumDepth(const Image *image, QuantumInfo *quantum_info, const size_t depth) {
  assert(image != NULL);
  assert(quantum_info != NULL);
  assert(ImageSignatureOK(image) && QuantumInfoSignatureOK(quantum_info));

#if defined(MAGICKCORE_DEBUG)
  (void)LogMagickEvent(CoderEvent, GetMagickModule(), "  image filename: %s", image->filename);
#endif

